import requests

url = "https://api.example.com/v1/widgets"

payload = {
    "object": "widget",
    "id": "string",
    "material": { "name": "string" },
    "shape": { "object": "round" },
    "parts": [
        {
            "object": "part",
            "sku": "string"
        }
    ],
    "assembly": {
        "id": "string",
        "object": "assembly"
    }
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)

